            aOrbiterF = RotL64((aOrbiterF * 0x1C25B2E504EAE195ULL), 35U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterH) + 0x4B59590956FBB2ABULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterC) ^ 0x0A27360C5C3B26F1ULL;
