            //
            aOrbiterI = (((aOrbiterI + aOrbiterE) + 0x8C31D0E11D2A66DEULL) + aOrbiterUpdateSaltF[(((31U - aIndex) + 21U)) & S_SALT1]) + aNonceWordN;
            aOrbiterD = (aOrbiterD ^ aOrbiterI) ^ 0x9AC2C947A09A7C2BULL;
            aOrbiterD = RotL64((aOrbiterD * 0x1D3D668D53DD7155ULL), 41U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterJ) + 0x60733A7C075CF6EDULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterF) ^ 0xF659A4E651BB3540ULL) ^ aNonceWordD;
