            //
            aOrbiterH = (aOrbiterH + aOrbiterA) + 0x1F60A7EDB23A969BULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterH) ^ 0x2CCA0D0E8DFDDCF2ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x8E5E1AA40E597149ULL), 3U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterF) + 0x19458E1BCA3EDBA2ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterA) ^ 0x0DDE241B858A0E77ULL;
