            //
            aWandererI = aWandererI + ((((RotL64(aScatter, 14U) + aOrbiterC) + RotL64(aOrbiterF, 52U)) + RotL64(aCarry, 19U)) + aNonceWordJ);
            aWandererJ = aWandererJ ^ (((RotL64(aPrevious, 51U) + RotL64(aOrbiterD, 35U)) + aOrbiterE) + aWandererUpdateSaltB[(((31U - aIndex) + 15U)) & S_SALT1]);
            aWandererH = aWandererH + ((RotL64(aCross, 39U) + aOrbiterF) + RotL64(aOrbiterK, 39U));
