            //
            aOrbiterA = ((aWandererI + RotL64(aIngress, 12U)) + RotL64(aCarry, 23U)) + 0xCA3CFB1765F4CEDFULL;
            aOrbiterC = ((aWandererJ + RotL64(aScatter, 21U)) + RotL64(aCarry, 39U)) + 0xDCB240A2ACB0538FULL;
            aOrbiterI = ((aWandererG + RotL64(aPrevious, 43U)) + RotL64(aCarry, 3U)) + 0x6A59F54CDEE544ACULL;
            aOrbiterB = ((aWandererE + RotL64(aCross, 27U)) + 0x6E13326D9B22B8DBULL) + aKeyRotateAOrbiterAssignSaltB[((aIndex + 15U)) & S_SALT1];
            aOrbiterH = (aWandererK + RotL64(aIngress, 35U)) + 0x5FDFC775E4239381ULL;
            aOrbiterJ = (aWandererD + RotL64(aCross, 3U)) + 0xAA8ADF861C12AA3EULL;
            aOrbiterE = ((aWandererA + RotL64(aPrevious, 51U)) + 0x36A15FC38411F5ECULL) + aKeyRotateAOrbiterAssignSaltD[((aIndex + 27U)) & S_SALT1];
            //
            aOrbiterA = (aOrbiterA + aOrbiterC) + 0x0654D5D02B8115CDULL;
