            //
            aOrbiterC = ((aOrbiterC + aOrbiterH) + 0xBF45B6BD0248EDDAULL) + aKeyRotateAOrbiterUpdateSaltE[((aIndex + 22U)) & S_SALT1];
            aOrbiterJ = (aOrbiterJ ^ aOrbiterC) ^ 0x0F0B0F1C64ABF895ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x25AE04C13F3BBA8DULL), 43U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterE) + 0x19AF573C504C0F27ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterH) ^ 0xC77031F5EE120675ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x547E691054880F47ULL), 53U);
            //
            aIngress = RotL64(aOrbiterJ, 57U) ^ aOrbiterE;
            aIngress = aIngress + (RotL64(aOrbiterH, 21U) ^ aOrbiterA);
            aIngress = aIngress + (aOrbiterI ^ RotL64(aOrbiterC, 47U));
            aIngress = aIngress + RotL64(aOrbiterB, 29U);
            aIngress = TwistMix64::DiffuseB((aIngress + aScatter));
            //
            aWandererD = aWandererD ^ ((RotL64(aScatter, 21U) + RotL64(aOrbiterC, 21U)) + aOrbiterA);
            aWandererA = aWandererA + (((RotL64(aPrevious, 28U) + RotL64(aOrbiterB, 27U)) + aOrbiterI) + aKeyRotateAWandererUpdateSaltF[(((31U - aIndex) + 28U)) & S_SALT1]);
            aWandererG = aWandererG ^ (((RotL64(aCross, 11U) + aOrbiterH) + RotL64(aOrbiterC, 14U)) + aKeyRotateAWandererUpdateSaltA[(((31U - aIndex) + 17U)) & S_SALT1]);
