            aCross = TwistMix64::DiffuseB((aCross ^ aKeyRotateADomainWordCross));
            //
            aScatter = (RotL64(aPrevious, 23U) + RotL64(aCarry, 11U)) + (RotL64(aIngress, 60U) ^ RotL64(aCross, 41U));
            aScatter = TwistMix64::DiffuseC((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterB = ((aWandererB + RotL64(aPrevious, 27U)) + RotL64(aCarry, 23U)) + 0xCDEDAE5F9B4D1391ULL;
            aOrbiterI = ((aWandererC + RotL64(aScatter, 57U)) + 0x1051B595F8C58977ULL) + aKeyRotateAOrbiterAssignSaltA[((aIndex + 11U)) & S_SALT1];
            aOrbiterC = ((aWandererG + RotL64(aIngress, 43U)) + RotL64(aCarry, 53U)) + 0x538C737DD512E753ULL;
            aOrbiterK = (aWandererK + RotL64(aCross, 21U)) + 0x0EAB920C182CC141ULL;
            aOrbiterH = (aWandererH + RotL64(aScatter, 14U)) + 0xE7209EBA39849CA1ULL;
            aOrbiterA = ((aWandererE + RotL64(aCross, 5U)) + RotL64(aCarry, 11U)) + 0xA7259CE304297527ULL;
            aOrbiterD = ((aWandererI + RotL64(aPrevious, 37U)) + 0xC1D63F9591347B12ULL) + aKeyRotateAOrbiterAssignSaltE[((aIndex + 29U)) & S_SALT1];
            //
            aOrbiterB = (aOrbiterB + aOrbiterI) + 0xFD6BF395674DBF84ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterB) ^ 0x1AD43DBE23B5A0A4ULL;
            aOrbiterC = RotL64((aOrbiterC * 0x0703DDCE49379F11ULL), 39U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterK) + 0xDC9AE39B7F6F5F53ULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterC) ^ 0x7A2F54FB7F55EBFAULL) ^ aKeyRotateAOrbiterUpdateSaltF[(((31U - aIndex) + 26U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0x7A8E680F85924251ULL), 51U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterH) + 0x10315781C5A9315BULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterA) ^ 0x444D9CC2E2D3B6D0ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x6C968613B2514F4FULL), 29U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterD) + 0x79EF07C89A9296BAULL;
            aOrbiterK = ((aOrbiterK ^ aOrbiterI) ^ 0x9ED5774FDB1F3F94ULL) ^ aKeyRotateAOrbiterUpdateSaltE[(((31U - aIndex) + 14U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0xD5378C3DEBED0A2BULL), 5U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterB) + 0xD25A7D7E0638BB88ULL;
            aOrbiterD = ((aOrbiterD ^ aOrbiterH) ^ 0x8F0D95CC851385CAULL) ^ aKeyRotateAOrbiterUpdateSaltD[(((31U - aIndex) + 7U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0x0D340F398DE9CC39ULL), 57U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterA) + 0xEF8A4BE399124230ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterK) ^ 0x1A3CE1CF9F7E1898ULL;
            aOrbiterB = RotL64((aOrbiterB * 0x43DE4286F8ABF157ULL), 21U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterC) + 0xF9B28A7F07414D42ULL;
            aOrbiterA = ((aOrbiterA ^ aOrbiterD) ^ 0xCCD07515080D58BDULL) ^ aKeyRotateAOrbiterUpdateSaltB[((aIndex + 21U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0x87E8EFC51BBF3E5DULL), 11U);
            //
            aIngress = aOrbiterC ^ RotL64(aOrbiterH, 29U);
            aIngress = aIngress + (aOrbiterI ^ RotL64(aOrbiterA, 57U));
            aIngress = aIngress + (RotL64(aOrbiterB, 11U) ^ aOrbiterD);
