            aIngress = TwistMix64::DiffuseC((aIngress + aScatter));
            //
            aWandererB = aWandererB + ((RotL64(aScatter, 41U) + aOrbiterH) + RotL64(aOrbiterC, 21U));
            aWandererH = aWandererH ^ (((RotL64(aPrevious, 19U) + aOrbiterC) + RotL64(aOrbiterB, 13U)) + aKeyRotateAWandererUpdateSaltC[((aIndex + 28U)) & S_SALT1]);
            aWandererI = aWandererI + ((((RotL64(aCross, 11U) + aOrbiterK) + RotL64(aOrbiterA, 57U)) + RotL64(aCarry, 47U)) + aKeyRotateAWandererUpdateSaltB[(((31U - aIndex) + 25U)) & S_SALT1]);
            aWandererC = aWandererC ^ ((RotL64(aIngress, 57U) + RotL64(aOrbiterB, 51U)) + aOrbiterI);
            aWandererK = aWandererK + (((RotL64(aPrevious, 28U) + aOrbiterK) + RotL64(aOrbiterI, 36U)) + RotL64(aCarry, 23U));
